package com.tecsup.controller; import com.tecsup.model.Cliente; import com.tecsup.repository.ClienteRepository; import com.tecsup.dto.ClienteRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import org.springframework.web.bind.annotation.ExceptionHandler; @RestController @RequestMapping("/api/clientes") public class ClienteController { private final ClienteRepository repo; public ClienteController(ClienteRepository r){repo=r;} @GetMapping public List<Cliente> all(){return repo.findAll();} @GetMapping("/{id}") public Cliente one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Cliente no encontrado: "+id));} @PostMapping public ResponseEntity<Cliente> create(@Valid @RequestBody ClienteRequest r){Cliente e=new Cliente(); e.setNombre(r.nombre()); e.setApellidos(r.apellidos()); e.setDireccion(r.direccion()); e.setEstado(r.estado()); e.setNroDni(r.nroDni()); return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(e));} @PutMapping("/{id}") public Cliente update(@PathVariable Long id,@Valid @RequestBody ClienteRequest r){Cliente e=one(id); e.setNombre(r.nombre()); e.setApellidos(r.apellidos()); e.setDireccion(r.direccion()); e.setEstado(r.estado()); e.setNroDni(r.nroDni()); return repo.save(e);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){repo.delete(one(id));return ResponseEntity.noContent().build();} }

@RestControllerAdvice class ApiErrors { @ExceptionHandler(NoSuchElementException.class) org.springframework.http.ResponseEntity<?> missing(Exception e){return org.springframework.http.ResponseEntity.status(404).body(java.util.Map.of("error",e.getMessage()));} @ExceptionHandler({org.springframework.web.bind.MethodArgumentNotValidException.class,IllegalArgumentException.class}) org.springframework.http.ResponseEntity<?> bad(Exception e){return org.springframework.http.ResponseEntity.badRequest().body(java.util.Map.of("error",e.getMessage()));} }
